let textOverrides = {};
function rewriteValue(value){const trimmed=String(value??'').trim();return Object.hasOwn(textOverrides,trimmed)?String(value).replace(trimmed,textOverrides[trimmed]):value;}
function applyTextOverrides(root=document.body){
  if(!root||!Object.keys(textOverrides).length)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(node){return node.parentElement?.closest('script,style,textarea')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT;}});
  const textNodes=[];while(walker.nextNode())textNodes.push(walker.currentNode);
  for(const node of textNodes){const next=rewriteValue(node.nodeValue);if(next!==node.nodeValue)node.nodeValue=next;}
  root.querySelectorAll?.('[aria-label],[title],[placeholder],[alt]').forEach(el=>{for(const attr of ['aria-label','title','placeholder','alt'])if(el.hasAttribute(attr)){const next=rewriteValue(el.getAttribute(attr));if(next!==el.getAttribute(attr))el.setAttribute(attr,next);}});
}
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[c]);
const api = async (url, options = {}) => {
  const response = await fetch(url, { credentials:'same-origin', ...options, headers:{ ...(options.body ? {'Content-Type':'application/json'} : {}), ...(options.headers || {}) } });
  const data = await response.json().catch(() => ({error:`استجابة غير متوقعة من الخادم (${response.status})` }));
  if (!response.ok) { const error=new Error(data.error || 'تعذر تنفيذ الطلب'); if(url!=='/api/auth/login'&&error.message.includes('انتهت صلاحية اشتراك'))login(error.message); throw error; }
  return data;
};
