function setThemeCatalog(catalog=[],fonts=[]){window.themeCatalog=Array.isArray(catalog)?catalog.filter(theme=>/^theme-[a-f0-9]{12}$/.test(theme?.id||'')):[];window.fontCatalog=Array.isArray(fonts)?fonts.filter(font=>/^font-[a-f0-9]{12}$/.test(font?.id||'')):[];}
function themeLabel(id){return id==='stap-default'?'stap Default Theme':window.themeCatalog?.find(theme=>theme.id===id)?.name||'stap Default Theme';}
function isKnownTheme(id){return id==='stap-default'||window.themeCatalog?.some(theme=>theme.id===id)||false;}
function applyCentralTheme(data,surface='dashboard'){
  if(!data||!window.ThemeSystem)return;
  window.activeCentralTheme={data,surface};
  if(!window.centralThemeModeListener){window.centralThemeModeListener=()=>{const current=window.activeCentralTheme;if(current)applyCentralTheme(current.data,current.surface);};matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',window.centralThemeModeListener);}
  const assigned=data.assignedTheme||data;
  const appearance=data.overrides?.appearance||assigned.appearance||data.defaultTheme?.appearance||'system';
  const dark=appearance==='dark'||(appearance==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);
  const mode=dark?'dark':'light';
  const baseTheme=data.defaultTheme||window.ThemeSystem.DEFAULT_THEME,overrides=data.overrides||{};
  const resolved=window.ThemeSystem.resolve(baseTheme,assigned,overrides,surface,'',mode);
  for(const [component] of window.ThemeSystem.COMPONENTS){const layer=window.ThemeSystem.resolve(baseTheme,assigned,overrides,surface,component,mode);resolved.components[component]=layer.components[component];}
  window.themeResolvedAssets=resolved.assets||{};
  window.ThemeSystem.setCssVariables(document.documentElement,resolved,mode);
  const uploadedFonts=data.fonts||window.fontCatalog||[];let fontStyles=document.getElementById('uploadedThemeFonts');if(!fontStyles){fontStyles=document.createElement('style');fontStyles.id='uploadedThemeFonts';document.head.append(fontStyles);}fontStyles.textContent=uploadedFonts.filter(font=>/^font-[a-f0-9]{12}$/.test(font.id)).map(font=>`@font-face{font-family:"${font.id}";src:url("/api/public/fonts/${font.id}") format("woff2");font-display:swap}`).join('');
  if(document.body){document.body.dataset.themeMode=mode;document.body.dataset.sidebarPosition=resolved.layout.sidebarPosition;document.body.dataset.showLogo=String(resolved.layout.showLogo);document.body.dataset.showStoreName=String(resolved.layout.showStoreName);document.body.dataset.showPoweredBy=String(resolved.layout.showPoweredBy);document.body.dataset.themeMotion=String(Boolean(resolved.motion.enabled));}
  const assets=resolved.assets||{};document.querySelectorAll('.stap-platform-logo').forEach(img=>{img.src=assets[mode==='dark'?'logoDark':'logoLight']||`/assets/stap/logo-${mode}.svg`;});
  const iconHref=window.currentUser?.role==='admin'?siteIcon||assets.favicon||`/assets/stap/app-icon-${mode}.svg`:assets.favicon||window.storeInfo?.iconImage||`/assets/stap/app-icon-${mode}.svg`;
  for(const selector of ['link[rel="icon"]','link[rel="apple-touch-icon"]']){let link=document.querySelector(selector);if(!link){link=document.createElement('link');link.rel=selector.includes('apple')?'apple-touch-icon':'icon';document.head.append(link);}link.href=iconHref;}
  document.documentElement.dataset.themeMode=mode;
}
function applyStoreTheme(theme,definition,surface='dashboard'){if(window.themeData)applyCentralTheme(window.themeData,surface);else if(definition?.themeData)applyCentralTheme(definition.themeData,surface);}
function applyAdminTheme(){if(window.platformTheme)applyCentralTheme({defaultTheme:window.ThemeSystem.DEFAULT_THEME,assignedTheme:window.platformTheme,overrides:{}},'dashboard');}
function toast(message) { const el=document.createElement('div'); el.className='toast'; el.textContent=message; document.body.append(el); setTimeout(()=>el.remove(),2800); }
function swapStatusText(element,next){if(!element||element.textContent===next)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches){element.textContent=next;return;}clearTimeout(element.__nawaTextTimer);element.classList.add('t-text-swap','is-exit');const duration=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--text-swap-dur'))||200;element.__nawaTextTimer=setTimeout(()=>{element.textContent=next;element.classList.remove('is-exit');element.classList.add('is-enter-start');void element.offsetHeight;element.classList.remove('is-enter-start');},duration);}
