  const nav=admin?[["home","▦","المتاجر"],["themes","◐","محرر الثيمات"],["settings","⚙","إعدادات النظام"]]:storeNav.filter(([id])=>(window.storeInfo?.visibleSections||['home','menu','design']).includes(id));
  const extraTranslations={'التواصل مع الأدمن':'Contact admin','تواصل مع الأدمن':'Contact admin','محادثة الأدمن':'Admin chat','إظهار التواصل لصاحب المتجر':'Show chat for the store owner','يمكن تفعيل المحادثة أو إيقافها لهذا المتجر بشكل مستقل.':'Chat can be enabled or disabled for this store.','تخصيص بطاقة العميل':'Customize the customer card','تتكيف البطاقة تلقائياً مع شاشة العميل وتظهر بحجم كبير.':'The card automatically adapts to the customer’s screen.','حشو محتوى البطاقة':'Card content padding','تقويس الزوايا':'Corner radius','حجم النص':'Text size','قوة الظل':'Shadow strength','يتغير حجم البطاقة تلقائياً ليلائم شاشة العميل.':'The card automatically adapts to the customer’s screen.','تخصيص CSS لكل واجهة':'Custom CSS per page','كل محرر يخص واجهة واحدة. ابدأ المحددات بـ':'Each editor applies to one page. Start selectors with','قواعد @media للعرض أو الارتفاع مدعومة؛ الروابط و @import ممنوعة.':'Width/height @media rules are supported; URLs and @import are blocked.','واجهة المتجر':'Store dashboard','بطاقة العميل':'Customer card','شاشة البانر وQR':'Banner and QR screen','نحن هنا لمساعدتك':'We’re here to help','جاري تحميل المحادثة…':'Loading conversation…','لا توجد رسائل. ابدأ المحادثة هنا.':'No messages yet. Start the conversation here.','اكتب رسالة…':'Write a message…','إرسال':'Send'};Object.assign(translations,extraTranslations);for(const [arabic,english] of Object.entries(extraTranslations))reverseTranslations[english]=arabic;
  if(!admin&&window.storeInfo?.chatEnabled!==false)nav.push(['chat','✉','التواصل مع الأدمن']);
