  if(!enabledSections.includes(page)){if(enabledSections.length){toast('هذا القسم غير متاح لهذا المتجر');page=enabledSections[0];}else{shell(user,'home','<div class="panel card empty">الأقسام غير متاحة لهذا المتجر. تواصل مع الأدمن.</div>');document.getElementById('pageTitle').textContent='المتجر';return;}}
