  if(page==='menu'){
    const body=`${sectionHead('قائمة الأصناف','أدرج ما يبيعه متجرك وحدد تقدير وقت التحضير.') }<div class="panel card catalog-manage"><div class="catalog-callout"><span class="shop-avatar">☷</span><div><strong>أصناف متجرك</strong><small>تظهر الأصناف المتاحة للعميل مع البحث والتصنيف والمدة التقديرية.</small></div></div><button class="button primary" id="openCatalog">إدارة القائمة <span>←</span></button></div><div class="inline-alert" style="margin-top:13px">يمكن للأدمن أو صاحب المتجر إدارة الأصناف. إخفاء صنف يوقف ظهوره في الطلبات الجديدة، وتبقى الطلبات السابقة كما هي.</div>${subscriptionNotice(storeConfig)}`;
    shell(user,'menu',body);document.getElementById('pageTitle').textContent='قائمة الأصناف';document.getElementById('openCatalog').onclick=()=>catalogDialog(window.storeInfo,false);return;
  }
