    const info=window.storeInfo||{};
    const body=`${sectionHead('تصميم المتجر','خصص عبارة شاشة الترحيب والبنر. يدير الأدمن ثيم المتجر من محرر الثيمات.') }<div class="grid content-grid"><article class="panel card"><form id="designForm" class="form-stack"><label class="field"><span>عبارة شاشة البانر</span><input class="input" name="bannerText" maxlength="90" value="${esc(info.bannerText||'أهلاً بك — اطلب واستمتع')}"></label><div class="shop-hero ${themeClass(info.theme)}" style="margin-top:8px"><div class="hero-copy"><span class="hero-kicker">STAP · ${esc(info.name||user.name||'متجرك')}</span><h2>أهلاً بك</h2><p>امسح رمز طلبك لمتابعته.</p></div></div><button class="button primary" type="submit">حفظ البانر</button></form></article><aside class="panel card"><div class="eyebrow">روابط المتجر</div><h2 class="section-title" style="margin-top:8px">شاركها بسهولة</h2><p class="section-sub" style="margin-bottom:17px">هذه الروابط دائمة لمتجرك.</p><div class="form-stack"><a class="button soft" target="_blank" href="/screen/${encodeURIComponent(info.slug||'')}">شاشة البانر وQR ↗</a><div class="inline-alert">تخصيص الثيمات متاح للأدمن فقط.</div></div></aside></div>${subscriptionNotice(storeConfig)}`;
    shell(user,'design',body);document.getElementById('pageTitle').textContent='تصميم المتجر';
    document.getElementById('designForm').onsubmit=async e=>{e.preventDefault();await api('/api/shop/settings',{method:'PATCH',body:json({bannerText:e.target.bannerText.value})});info.bannerText=e.target.bannerText.value;toast('تم حفظ عبارة البانر');};
