  const completedOrders=orders.filter(o=>o.status==='completed');
  const waiting=activeOrders.filter(o=>o.status==='queued').length,prep=activeOrders.filter(o=>o.status==='preparing').length,ready=activeOrders.filter(o=>o.status==='ready').length;
  const renderOrder=o=>`<article class="order-card"><div class="order-no">#${esc(o.number)}</div><div><div class="order-title">${o.customerName?`<span class="subtle">${esc(o.customerName)} · </span>`:''}${esc(o.item)}</div><div class="order-meta">${new Date(o.createdAt).toLocaleTimeString(uiLocale(),{hour:'2-digit',minute:'2-digit'})} · ${o.prepMinutes?`تحضير نحو ${o.prepMinutes} د`:'طلب يدوي'}</div></div><div class="order-status ${o.status==='ready'?'ready':o.status==='preparing'?'preparing':''}">${labels[o.status]}</div><div class="status-actions">${o.status==='queued'?`<button class="button soft next-status" data-status="${esc(o.id)}" data-next="preparing">بدء التحضير</button>`:o.status==='preparing'?`<button class="button lime next-status" data-status="${esc(o.id)}" data-next="ready">جاهز للاستلام</button>`:o.status==='ready'?`<button class="button primary next-status" data-status="${esc(o.id)}" data-next="completed">تأكيد التسليم</button>`:''}</div></article>`;
  const activeList=activeOrders.length?activeOrders.map(renderOrder).join(''):`<div class="panel empty active-empty"><strong>لا توجد طلبات قيد التنفيذ</strong><span>طلبات متجرك الجديدة ستظهر هنا.</span><button class="button primary" id="emptyCreateOrder">＋ إنشاء طلب جديد</button></div>`;
